package main

import (
	"context"
	"log"
	"net"
	"sync"
	"sync/atomic"
	"time"
	"unsafe"

	"google.golang.org/grpc"
	pb "myservice/proto"
)

type FeatureConfig struct {
	Name      string
	Enabled   bool
	RateLimit int
	Metadata  map[string]string
}

type ConfigStore struct {
	mu       sync.RWMutex
	current  unsafe.Pointer // *FeatureConfig
	previous unsafe.Pointer // *FeatureConfig
	epoch    uint64
}

func NewConfigStore(initial *FeatureConfig) *ConfigStore {
	cs := &ConfigStore{}
	cs.current = unsafe.Pointer(initial)
	cs.previous = unsafe.Pointer(initial)
	cs.epoch = 0
	return cs
}

// SwapConfig atomically replaces the current config with a new one.
// The previous config is retained for graceful drain.
func (cs *ConfigStore) SwapConfig(newCfg *FeatureConfig) {
	cs.mu.Lock()
	oldCurrent := cs.current
	cs.previous = oldCurrent
	cs.current = unsafe.Pointer(newCfg)
	atomic.AddUint64(&cs.epoch, 1)
	cs.mu.Unlock()
}

// AcquireConfig returns the current config pointer and the epoch.
// Callers must call ReleaseConfig when done.
func (cs *ConfigStore) AcquireConfig() (*FeatureConfig, uint64) {
	epoch := atomic.LoadUint64(&cs.epoch)
	// Load current pointer without holding lock for performance
	ptr := atomic.LoadPointer(&cs.current)
	return (*FeatureConfig)(ptr), epoch
}

// ReleaseConfig signals that the caller is done with the config.
// If epoch has advanced by more than 1, the previous pointer is invalidated.
func (cs *ConfigStore) ReleaseConfig(epoch uint64) {
	currentEpoch := atomic.LoadUint64(&cs.epoch)
	if currentEpoch > epoch+1 {
		// Previous has been recycled; this is a no-op signal
		_ = currentEpoch
	}
}

type FeatureFlagService struct {
	pb.UnimplementedFeatureFlagServiceServer
	store       *ConfigStore
	configPool  sync.Pool
	reloadChan  chan *FeatureConfig
}

func NewFeatureFlagService() *FeatureFlagService {
	initialCfg := &FeatureConfig{
		Name:      "default",
		Enabled:   true,
		RateLimit: 100,
		Metadata:  map[string]string{"version": "1.0"},
	}

	svc := &FeatureFlagService{
		store:      NewConfigStore(initialCfg),
		reloadChan: make(chan *FeatureConfig, 4),
		configPool: sync.Pool{
			New: func() interface{} {
				return &FeatureConfig{
					Metadata: make(map[string]string),
				}
			},
		},
	}

	go svc.configReloader()
	return svc
}

func (s *FeatureFlagService) configReloader() {
	for newCfg := range s.reloadChan {
		// Swap in the new config
		s.store.SwapConfig(newCfg)

		// After two swaps, recycle the config that was 'previous'
		// back into the pool for memory efficiency
		time.AfterFunc(50*time.Millisecond, func() {
			s.store.mu.RLock()
			prev := (*FeatureConfig)(s.store.previous)
			s.store.mu.RUnlock()
			if prev != nil {
				// Clear and return to pool
				prev.Name = ""
				prev.Enabled = false
				prev.RateLimit = 0
				for k := range prev.Metadata {
					delete(prev.Metadata, k)
				}
				s.configPool.Put(prev)
			}
		})
	}
}

func (s *FeatureFlagService) GetFeatureFlag(ctx context.Context, req *pb.GetFeatureFlagRequest) (*pb.GetFeatureFlagResponse, error) {
	cfg, epoch := s.store.AcquireConfig()
	defer s.store.ReleaseConfig(epoch)

	// Simulate some processing that takes time
	// During this window, the config could be recycled
	result := &pb.GetFeatureFlagResponse{
		Name:      cfg.Name,
		Enabled:   cfg.Enabled,
		RateLimit: int32(cfg.RateLimit),
	}

	// Access metadata - this is where use-after-free can occur
	// if configReloader recycled this config back to pool
	if val, ok := cfg.Metadata[req.GetMetadataKey()]; ok {
		result.MetadataValue = val
	}

	return result, nil
}

func (s *FeatureFlagService) UpdateFeatureFlag(ctx context.Context, req *pb.UpdateFeatureFlagRequest) (*pb.UpdateFeatureFlagResponse, error) {
	newCfg := s.configPool.Get().(*FeatureConfig)
	newCfg.Name = req.GetName()
	newCfg.Enabled = req.GetEnabled()
	newCfg.RateLimit = int(req.GetRateLimit())
	newCfg.Metadata["version"] = req.GetVersion()

	s.reloadChan <- newCfg

	return &pb.UpdateFeatureFlagResponse{Success: true}, nil
}

func main() {
	lis, err := net.Listen("tcp", ":50051")
	if err != nil {
		log.Fatalf("failed to listen: %v", err)
	}

	grpcServer := grpc.NewServer()
	svc := NewFeatureFlagService()
	pb.RegisterFeatureFlagServiceServer(grpcServer, svc)

	log.Println("Feature flag service starting on :50051")
	if err := grpcServer.Serve(lis); err != nil {
		log.Fatalf("failed to serve: %v", err)
	}
}
